        int full=(1<<target.size())-1;
        vector<int> dp(full+1,INT_MAX);
        dp[0]=0;
        for(int mask=0;mask<=full;++mask){
            if(dp[mask]==INT_MAX)continue;
            for(string& sticker:stickers){
                int counts[26]{
                };
