                int next=mask;
                for(int i=0;i<(int)target.size();++i)if(!(next&(1<<i))&&counts[target[i]-'a']>0){
                    --counts[target[i]-'a'];
                    next|=1<<i;
                }
                if(next!=mask)dp[next]=min(dp[next],dp[mask]+1);
